$(1)$ If $z$ is the unique closed ${\mathsf{k}}$-point of $Z_1$ then $\gamma_{Z_1}({\mathscr{O}}_z) \cong {\mathscr{O}}_X \cong \pi_*{\mathscr{O}}_{\widetilde{X}}$. 
oindent$(2)$ Let $z \in Z_2$ be a closed ${\mathsf{k}}$-point and let ${\mathscr{E}}_z := \gamma_{Z_2}({\mathscr{O}}_z) \in {\mathbf{D}}(X)$ be the corresponding object. Then  egin{itemize} \item[(a)] if the component of $Z_2$ containing $z$ is reduced and corresponds to the $i$-th blowup center, then  egin{equation*} {\mathscr{E}}_z \cong \pi_*{\mathscr{O}}_{\widetilde{X}}(h-e_i); \end{equation*} \item[(b)] if the component of $Z_2$ containing $z$ has length $2$ then  egin{equation*} {\mathscr{E}}_z \cong \pi_*{\mathscr{O}}_{\widetilde{X}}(h-e_1) \cong \pi_*{\mathscr{O}}_{\widetilde{X}}(h - e_2); \end{equation*} \item[(c)] if the component of $Z_2$ containing $z$ has length $3$, then  egin{equation*} {\mathscr{E}}_z \cong \pi_*{\mathscr{O}}_{\widetilde{X}}(h-e_1) \cong \pi_*{\mathscr{O}}_{\widetilde{X}}(h - e_2) \cong \pi_*{\mathscr{O}}_{\widetilde{X}}(h - e_3). \end{equation*} \end{itemize} 
oindent$(3)$ Let $z \in Z_3$ be a closed ${\mathsf{k}}$-point and let ${\mathscr{E}}_z := \gamma_{Z_3}({\mathscr{O}}_z) \in {\mathbf{D}}(X)$ be the corresponding object. Then  egin{itemize} \item[(a)] if the component of $Z_3$ containing $z$ is reduced then  egin{equation*} {\mathscr{E}}_z \cong \pi_*{\mathscr{O}}_{\widetilde{X}}(h) \qquad	ext{or}\qquad {\mathscr{E}}_z \cong \pi_*{\mathscr{O}}_{\widetilde{X}}(2h - e_1 - e_2 - e_3); \end{equation*} \item[(b)] if the component of $Z_3$ containing $z$ has length $2$ then  egin{equation*} {\mathscr{E}}_z \cong \pi_*{\mathscr{O}}_{\widetilde{X}}(h) \cong \pi_*{\mathscr{O}}_{\widetilde{X}}(2h - e_1 - e_2 - e_3). \end{equation*} \end{itemize} In all these cases, ${\mathscr{E}}_z$ is a globally generated sheaf, and if $z \in Z_d$ then  egin{equation*} \dim H^0(X,{\mathscr{E}}_z) = d \qquad	ext{and}\qquad H^{i}(X,{\mathscr{E}}_z) = 0 \quad	ext{for $i 
e 0$}. \end{equation*}
